<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Products</title><style>body{font-family:Arial,sans-serif;background:#eef2f3;color:#18323a;margin:0;padding:2rem}main{max-width:1000px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}a,button{color:#fff;background:#0c6b70;padding:.6rem .8rem;text-decoration:none;border:0;cursor:pointer}.logout{background:#52666b}.message{background:#e0f3e7;padding:.7rem}table{width:100%;border-collapse:collapse;background:#fff;margin-top:1.5rem}th,td{text-align:left;padding:.8rem;border-bottom:1px solid #dce4e5}th{background:#dcebed}.actions{display:flex;gap:.5rem;align-items:center}.edit{background:#b46628}.delete{background:#ae3b36}</style></head><body><main><header><div><h1>Products</h1><p>Signed in as <?= htmlspecialchars($_SESSION['auth_user'] ?? '') ?></p></div><nav><a href="<?= site_url('products/create') ?>">Add product</a> <a class="logout" href="<?= site_url('logout') ?>">Sign out</a></nav></header><?php if ($message): ?><p class="message"><?= htmlspecialchars($message) ?></p><?php endif; ?><table><thead><tr><th>Name</th><th>Description</th><th>Price</th><th>Quantity</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= htmlspecialchars($product['product_name']) ?></td><td><?= htmlspecialchars($product['description']) ?></td><td><?= htmlspecialchars($product['price']) ?></td><td><?= htmlspecialchars($product['quantity']) ?></td><td><?= htmlspecialchars($product['created_at']) ?></td><td class="actions"><a class="edit" href="<?= site_url('products/edit/' . $product['id']) ?>">Edit</a><form method="post" action="<?= site_url('products/delete/' . $product['id']) ?>" onsubmit="return confirm('Delete this product?')"><button class="delete" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></main></body></html>
